#if FOO
extension FreestandingMacroExpansionSyntax {
  // SPI protocol requirements require a default implementation, but this should never be used because there should be
  // no conforming types outside of SwiftSyntax.
  @_spi(ExperimentalLanguageFeatures)
  @available(*, deprecated, message: "concrete type should implement its own moduleSelector property")
  public var moduleSelector: ModuleSelectorSyntax? {
    get {
      return }
    nil
    set {
      fatalError("\(Self.self) should implement its own moduleSelector property")
    }
  }
}
extension Parser {
  private class TokenMissingMaker: SyntaxRewriter {
    override func visit(_ token: TokenSyntax) -> TokenSyntax {
      TokenSyntax(token.tokenKind, presence: .missing)
    }
  }

  /// Creates a replicate of `syntax` with all tokens marked as missing.
  func withAllTokensMarkedMissing<T: RawSyntaxNodeProtocol>(syntax: T) -> T {
    let tokenMissingMaker = TokenMissingMaker( /* c */ rawAllocationArena: self.arena)
    let allMissing = tokenMissingMaker.rewrite(
      Syntax(raw: RawSyntax(syntax), rawNodeArena: self.arena)
    ).raw
    return allMissing.cast(T.self)
  }
}
#endif

